// bảng nổi dưới chuông
function renderNotiPanel(){
  $("#notiList").innerHTML=NOTI.items.slice(0,30).map(n=>`<div class="np-item ${n.read?"":"unread"}" data-nid="${esc(n.id)}">
      <span class="dot"></span>
      <div><div class="nk ${esc(n.kind)}">${esc(NK[n.kind]||n.kind)}</div><div class="t">${esc(n.title)}</div>
      ${n.body?`<div class="sub">${esc(n.body)}</div>`:""}<div class="sub" data-ago="${n.ts}">${ago(n.ts)}</div></div></div>`).join("")
    ||'<div class="np-empty">Chưa có thông báo nào.</div>';
}
function setNotiOpen(on){
  const b=$("#notiBtn");$("#notiPanel").hidden=!on;b.classList.toggle("open",on);b.setAttribute("aria-expanded",String(on));
  if(on)renderNotiPanel();
}
$("#notiBtn").onclick=e=>{e.stopPropagation();setNotiOpen($("#notiPanel").hidden)};
$("#nPanelRead").onclick=()=>act("/api/notifications/read",{},"Đã đánh dấu đọc hết");
$("#notiAll").onclick=()=>setNotiOpen(false);
$("#notiList").onclick=e=>{
  const it=e.target.closest("[data-nid]");if(!it)return;
  const n=NOTI.items.find(x=>x.id===it.dataset.nid);if(!n)return;
  post("/api/notifications/read",{id:n.id}).catch(()=>{});
  setNotiOpen(false);
  if(n.task)go(taskUrl(n.task)+(n.kind==="xong"?"/ket-qua":""));
};
document.addEventListener("click",e=>{if(!$("#notiPanel").hidden&&!e.target.closest("#notiWrap"))setNotiOpen(false)});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("#notiPanel").hidden)setNotiOpen(false)});

